# -*- coding: utf-8 -*-
"""微信官方 Logo（PNG，内嵌 base64）"""

WX_LOGO_PNG_B64 = (
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    ""
)

_cached = None


def get_default_logo():
    """返回官方 Logo 的 PIL RGBA 图像"""
    global _cached
    if _cached is None:
        import base64
        from io import BytesIO
        from PIL import Image
        try:
            _cached = Image.open(BytesIO(base64.b64decode(WX_LOGO_PNG_B64))).convert("RGBA")
        except Exception:
            _cached = False
    return _cached
